0030_writes.sql:
-- 0030 writes track: dispatch lease (R5), unique reconcile tokens, tamper guards.
-- Contract: docs/contracts/04-writes.md, 05-grants.md (G-2, G-3, G-20), board R5.

ALTER TABLE operations ADD COLUMN lease_owner TEXT;
ALTER TABLE operations ADD COLUMN lease_expires_at TEXT;

-- A reconcile token names exactly one operation, so reconcile can never
-- confirm one operation by finding another's message.
CREATE UNIQUE INDEX operations_reconcile_token
    ON operations (reconcile_token) WHERE reconcile_token IS NOT NULL;

-- audit_log is append-only (G-20). Rows may be removed only up to the
-- checkpoint the pruning step records first (G-22).
CREATE TRIGGER audit_log_no_update BEFORE UPDATE ON audit_log
BEGIN
    SELECT RAISE(ABORT, 'audit_log is append-only (G-20)');
END;

CREATE TRIGGER audit_log_guarded_delete BEFORE DELETE ON audit_log
WHEN old.seq > COALESCE(
    (SELECT CAST(substr(value, 1, instr(value, ':') - 1) AS INTEGER)
       FROM system_state WHERE key = 'writes.audit_checkpoint_hash'), 0)
BEGIN
    SELECT RAISE(ABORT, 'audit_log rows are removed only through the checkpoint (G-22)');
END;

-- Grants are never deleted by use, revocation or expiry (G-2).
CREATE TRIGGER grants_no_delete BEFORE DELETE ON grants
WHEN old.compacted_at IS NULL
BEGIN
    SELECT RAISE(ABORT, 'grants are never deleted before compaction (G-2)');
END;

CREATE TRIGGER grants_terminal_is_final BEFORE UPDATE OF state ON grants
WHEN old.state IN ('spent', 'revoked', 'expired', 'declined', 'lapsed')
     AND new.state <> old.state
BEGIN
    SELECT RAISE(ABORT, 'a terminal grant state is final (G-4)');
END;

CREATE TRIGGER grants_immutable BEFORE UPDATE ON grants
WHEN old.state <> 'proposed' AND new.compacted_at IS old.compacted_at AND (
        new.kind <> old.kind
     OR new.source_id <> old.source_id
     OR new.content_sha256 <> old.content_sha256
     OR new.scope_json IS NOT old.scope_json
     OR new.granted_at IS NOT old.granted_at
     OR new.expires_at IS NOT old.expires_at)
BEGIN
    SELECT RAISE(ABORT, 'grant fields are immutable once active (G-3)');
END;

CREATE TRIGGER operations_no_delete BEFORE DELETE ON operations
WHEN old.compacted_at IS NULL
BEGIN
    SELECT RAISE(ABORT, 'operations are deleted only after compaction (W-25)');
END;

CREATE TRIGGER operations_intent_immutable BEFORE UPDATE OF intent_sha256 ON operations
WHEN new.intent_sha256 <> old.intent_sha256
BEGIN
    SELECT RAISE(ABORT, 'an operation''s intent hash never changes (W-1)');
END;

CREATE TRIGGER operations_terminal_is_final BEFORE UPDATE OF state ON operations
WHEN old.state IN ('confirmed', 'failed_clean', 'confirmed_absent', 'cancelled')
     AND new.state <> old.state
BEGIN
    SELECT RAISE(ABORT, 'a terminal operation state is final (W-6)');
END;

0120_mail_scan_all_folders.sql:
-- 0120 mail scan over every folder: one identity per message, sent mail, a held older span.
-- Writer: the attention track (src/chamberlain/attention/watermark.py). Contract: 07-attention.md A-20 to A-23.
-- Still no sender, subject or body here: only identities, times and a suggested card handle.

-- One row per message, whatever folders hold copies of it (owner ruling 2026-11-24).
ALTER TABLE mail_seen ADD COLUMN message_key TEXT NOT NULL DEFAULT '';
ALTER TABLE mail_seen ADD COLUMN sent INTEGER NOT NULL DEFAULT 0 CHECK (sent IN (0, 1));

UPDATE mail_seen SET message_key = COALESCE(
    NULLIF(
        lower(trim(trim((SELECT r.internet_message_id FROM refs r WHERE r.handle = mail_seen.handle)), '<>')),
        ''
    ),
    'loc:' || locator
);

-- Keep the oldest row of any message the old per-locator rule stored twice.
DELETE FROM mail_seen
    WHERE seq NOT IN (SELECT MIN(seq) FROM mail_seen GROUP BY source_id, message_key);

CREATE UNIQUE INDEX mail_seen_key ON mail_seen (source_id, message_key);

-- The scan now walks oldest first and keeps its frontier across ticks.
-- `scan_until` (newest-first frontier) is no longer used; an unfinished old scan restarts safely.
UPDATE mail_watermarks SET scan_until = NULL;
ALTER TABLE mail_watermarks ADD COLUMN scan_from TEXT;
ALTER TABLE mail_watermarks ADD COLUMN scan_width INTEGER;

-- An older span the harness did not read because it is more than a day back (A-23).
-- `held_from` moves forward as the owner-approved catch-up reads it.
ALTER TABLE mail_watermarks ADD COLUMN held_from TEXT;
ALTER TABLE mail_watermarks ADD COLUMN held_to TEXT;
ALTER TABLE mail_watermarks ADD COLUMN held_state TEXT
    CHECK (held_state IN ('asking', 'approved', 'declined'));
ALTER TABLE mail_watermarks ADD COLUMN held_estimate INTEGER;
ALTER TABLE mail_watermarks ADD COLUMN held_width INTEGER;

0140_action_important.sql:
-- 0140 an action may be marked important by the agent (owner ruling 2026-11-24): an important
-- appointment is its own flag, not a title prefix. Actions titled "Important..." before this
-- migration keep showing as important.
ALTER TABLE actions ADD COLUMN important INTEGER NOT NULL DEFAULT 0 CHECK (important IN (0, 1));
UPDATE actions SET important = 1 WHERE lower(title) LIKE 'important%';

0201_read_marked.sql:
-- 0201 the harness marks mail read after a pass report when the owner turned that on
-- (read_state.reporting_marks_read). One attempt per message, never repeated.
ALTER TABLE mail_seen ADD COLUMN read_marked_at TEXT;
-- The session that was shown the batch holding this message: what a report covers.
ALTER TABLE mail_seen ADD COLUMN delivered_session TEXT;
